document.querySelectorAll('input[type=date]').forEach(e=>{let d=new Date();let date=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');e.min=date;e.value=date});document.querySelectorAll('form[data-demo]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();let r=f.querySelector('[role=status]');r.textContent='Simulação concluída! Nenhuma solicitação foi enviada. Em um site real, esta etapa pode ser integrada ao atendimento do negócio.';r.focus()}));const products=[['Tricô Horizonte',189],['Camada Essencial',159],['Calça Movimento',229]];let bag=[];let lastFocus;const panel=document.querySelector('#cart');const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});function showCart(){lastFocus=document.activeElement;panel.hidden=false;document.querySelector('#overlay').hidden=false;document.body.style.overflow='hidden';document.querySelector('#close-cart').focus()}function closeCart(){panel.hidden=true;document.querySelector('#overlay').hidden=true;document.body.style.overflow='';lastFocus?.focus()}document.querySelector('#open-cart').onclick=showCart;document.querySelector('#close-cart').onclick=closeCart;document.querySelector('#overlay').onclick=closeCart;document.addEventListener('keydown',e=>{if(panel.hidden)return;if(e.key==='Escape')closeCart();if(e.key==='Tab'){let nodes=[...panel.querySelectorAll('button:not([disabled])')];let first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});function renderBag(){document.querySelector('#count').textContent=bag.length;let box=document.querySelector('#cart-items');box.replaceChildren();if(!bag.length){box.textContent='Sua sacola ainda está vazia.'}bag.forEach((item,i)=>{let a=document.createElement('div');a.className='cart-item';let text=document.createElement('p');text.textContent=products[item.id][0]+' · '+item.size+' · '+money(products[item.id][1]);let b=document.createElement('button');b.textContent='Remover';b.setAttribute('aria-label','Remover '+products[item.id][0]);b.onclick=()=>{bag.splice(i,1);renderBag();document.querySelector('#close-cart').focus()};a.append(text,b);box.append(a)});document.querySelector('#total').textContent='Total: '+money(bag.reduce((s,i)=>s+products[i.id][1],0));document.querySelector('#checkout').disabled=!bag.length;document.querySelector('#checkout-status').textContent=''}document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.add);const size=document.querySelector('#size-'+id).value;bag.push({id,size});renderBag();document.querySelector('#shop-status').textContent=products[id][0]+' ('+size+') adicionado à sacola.';showCart()});document.querySelector('#checkout').onclick=()=>{document.querySelector('#checkout-status').textContent='Simulação concluída. Nenhum pedido foi enviado ou cobrado. Obrigado por explorar a FORMA!'};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.product').forEach(p=>p.hidden=b.dataset.filter!=='all'&&b.dataset.filter!==p.dataset.type)});renderBag();